<script setup lang="ts">
import type { SpeechGenerationOutput } from '@proj-airi/stage-ui/utils/frieren-dual-speech'

import {
  Alert,
  SpeechPlaygroundOpenAICompatible,
  SpeechProviderSettings,
} from '@proj-airi/stage-ui/components'
import { useProviderValidation } from '@proj-airi/stage-ui/composables/use-provider-validation'
import { useProvidersStore } from '@proj-airi/stage-ui/stores/providers'
import {
  FRIEREN_DUAL_SPEECH_DEFAULT_API_KEY,
  FRIEREN_DUAL_SPEECH_DEFAULT_MODEL,
  FRIEREN_DUAL_SPEECH_DEFAULT_SPEED,
  FRIEREN_DUAL_SPEECH_DEFAULT_VOICE,
  requestFrierenDualSpeech,
} from '@proj-airi/stage-ui/utils/frieren-dual-speech'
import { FieldInput, FieldRange } from '@proj-airi/ui'
import { storeToRefs } from 'pinia'
import { computed, onMounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'

const providerId = 'frieren-dual-speech'
const providersStore = useProvidersStore()
const { providers } = storeToRefs(providersStore)
const { t } = useI18n()

const speed = ref<number>(
  (providers.value[providerId]?.speed as number | undefined) ?? FRIEREN_DUAL_SPEECH_DEFAULT_SPEED,
)
const model = computed({
  get: () => FRIEREN_DUAL_SPEECH_DEFAULT_MODEL,
  set: () => {},
})

const voice = computed({
  get: () => providers.value[providerId]?.voice as string | undefined || FRIEREN_DUAL_SPEECH_DEFAULT_VOICE,
  set: (value) => {
    ensureProviderRecord().voice = value
  },
})

const apiKeyConfigured = computed(() => !!providers.value[providerId]?.apiKey)

function ensureProviderRecord() {
  if (!providers.value[providerId])
    providers.value[providerId] = {}

  return providers.value[providerId]
}

onMounted(() => {
  const providerRecord = ensureProviderRecord()

  if (!providerRecord.model)
    providerRecord.model = FRIEREN_DUAL_SPEECH_DEFAULT_MODEL
  if (!providerRecord.voice)
    providerRecord.voice = FRIEREN_DUAL_SPEECH_DEFAULT_VOICE
  if (typeof providerRecord.speed !== 'number')
    providerRecord.speed = FRIEREN_DUAL_SPEECH_DEFAULT_SPEED
})

watch(speed, (value) => {
  ensureProviderRecord().speed = value
})

async function handleGenerateSpeech(input: string, voiceId: string): Promise<SpeechGenerationOutput> {
  const providerConfig = providersStore.getProviderConfig(providerId)
  return await requestFrierenDualSpeech(providerConfig, input, {
    speed: speed.value,
    voice: voiceId || voice.value,
  })
}

const {
  isValidating,
  isValid,
  validationMessage,
  forceValid,
} = useProviderValidation(providerId)
</script>

<template>
  <SpeechProviderSettings
    :provider-id="providerId"
    :default-model="FRIEREN_DUAL_SPEECH_DEFAULT_MODEL"
    :additional-settings="{ speed: FRIEREN_DUAL_SPEECH_DEFAULT_SPEED }"
    :placeholder="FRIEREN_DUAL_SPEECH_DEFAULT_API_KEY"
  >
    <template #voice-settings>
      <FieldInput
        v-model="voice"
        :label="t('settings.pages.providers.provider.frieren-dual-speech.fields.voice.label')"
        :description="t('settings.pages.providers.provider.frieren-dual-speech.fields.voice.description')"
        :placeholder="FRIEREN_DUAL_SPEECH_DEFAULT_VOICE"
      />
      <FieldRange
        v-model="speed"
        :label="t('settings.pages.providers.provider.common.fields.field.speed.label')"
        :description="t('settings.pages.providers.provider.common.fields.field.speed.description')"
        :min="0.5"
        :max="2"
        :step="0.01"
      />
    </template>

    <template #playground>
      <SpeechPlaygroundOpenAICompatible
        v-model:model-value="model"
        v-model:voice="voice as any"
        :show-voice-input="false"
        :title="t('settings.pages.providers.provider.frieren-dual-speech.playground.title')"
        :input-placeholder="t('settings.pages.providers.provider.frieren-dual-speech.playground.input-placeholder')"
        :test-voice-label="t('settings.pages.providers.provider.frieren-dual-speech.playground.test-button-label')"
        :test-voice-generating-label="t('settings.pages.providers.provider.frieren-dual-speech.playground.test-button-generating')"
        :missing-api-key-message="t('settings.pages.providers.provider.frieren-dual-speech.playground.missing-api-key')"
        :generate-speech="handleGenerateSpeech"
        :api-key-configured="apiKeyConfigured"
        :default-text="t('settings.pages.providers.provider.frieren-dual-speech.playground.default-text')"
      />
    </template>

    <template #advanced-settings>
      <Alert v-if="!isValid && isValidating === 0 && validationMessage" type="error">
        <template #title>
          <div class="w-full flex items-center justify-between">
            <span>{{ t('settings.dialogs.onboarding.validationFailed') }}</span>
            <button
              type="button"
              class="ml-2 rounded bg-red-100 px-2 py-0.5 text-xs text-red-600 font-medium transition-colors dark:bg-red-800/30 hover:bg-red-200 dark:text-red-300 dark:hover:bg-red-700/40"
              @click="forceValid"
            >
              {{ t('settings.pages.providers.common.continueAnyway') }}
            </button>
          </div>
        </template>
        <template #content>
          <div class="whitespace-pre-wrap break-all">
            {{ validationMessage }}
          </div>
        </template>
      </Alert>
      <Alert v-if="isValid && isValidating === 0" type="success">
        <template #title>
          {{ t('settings.dialogs.onboarding.validationSuccess') }}
        </template>
      </Alert>
    </template>
  </SpeechProviderSettings>
</template>

<route lang="yaml">
meta:
  layout: settings
  stageTransition:
    name: slide
</route>
